// ---- Configuration ----
const measurementName = "HFE";
const tag1Name = "MAQ20";
const tag2Name = "Temperature";

const fieldNames = [
    "T1", "T2", "T3"
];

// Scaling factor for each field
const scale = new Array(fieldNames.length).fill(0.0977);

// ---- Get Modbus Data ----
const data = msg.payload.data || msg.payload;

// ---- Build fields object ----
const fields = {};

// Use only the FIRST values in the incoming array
// Number of values = number of fieldNames
for (let i = 0; i < fieldNames.length; i++) {

    // Stop if the incoming array doesn't contain enough values
    if (i >= data.length) {
        break;
    }

    let raw = Number(data[i]);

    if (!Number.isFinite(raw)) {
        continue;
    }

    // Convert unsigned 16-bit → signed 16-bit
    if (raw > 32767) {
        raw -= 65536;
    }

    fields[fieldNames[i]] = raw * scale[i];
}

// ---- Build final payload ----
msg.payload = [{
    measurement: measurementName,
    tags: {
        Device: tag1Name,
        Quantity: tag2Name
    },
    fields: fields
}];

return msg;

// ---- Configuration ----
const measurementName = "HFE";
const tag1Name = "MAQ20";
const tag2Name = "Pressure";

const fieldNames = [
    "P1",
    "P2",
    "P3"
];

// ---- Get Modbus Data ----
// Use the incoming array directly
const modbusData = msg.payload;

// ---- Convert raw value to current (A) ----
const multiplier = 5.25 * 10 ** -6;

const mA = modbusData.map(value => Number(value) * multiplier);

// ---- Pressure configuration ----
const Pmax = 150;  // psi
const Pmin = 0;    // psi

const Amin = 0.004;  // 4 mA
const Amax = 0.020;  // 20 mA

// ---- Convert current → psi ----
// Only process the FIRST three channels
const psi = mA
    .slice(0, fieldNames.length)
    .map(i => (i - Amin) * ((Pmax - Pmin) / (Amax - Amin)) + Pmin);

// ---- Convert psi → bar ----
const bar = psi.map(p => 0.06894574 * p);

// ---- Build fields object ----
const fields = {};

for (let i = 0; i < fieldNames.length && i < bar.length; i++) {

    const raw = Number(bar[i]);

    if (!Number.isFinite(raw)) {
        continue;
    }

    fields[fieldNames[i]] = raw;
}

// ---- Build final payload ----
msg.payload = [{
    measurement: measurementName,
    tags: {
        Device: tag1Name,
        Quantity: tag2Name
    },
    fields: fields
}];

return msg;

