// ---- Configuration ----
const measurementName = "HFE";
const tag1Name = "MAQ20";
const tag2Name = "flowrate";

const fieldName = "HFE_flowrate";

//---- Get Modbus Data ----
// msg.payload contains 16 values
const modbusData = msg.payload;

// ---- Select item 4 ----
const rawValue = Number(modbusData[4]);

// ---- Convert raw value to current ----
const multiplier = 5.25 * 10 ** -6;
const mA = rawValue * multiplier;

// ---- Current scaling configuration ----
const flow_max = 3.5;     // gpm
const flow_min = 0.35;      // gpm

const Amin = 0.004;  // 4 mA
const Amax = 0.020;  // 20 mA

// ---- Convert 4–20 mA → 0–50 amps ----
const flowrate =
    (mA - Amin) *
    ((flow_max - flow_min) / (Amax - Amin)) +
    flow_min;

// ---- Build fields object ----
const fields = {};

if (Number.isFinite(flowrate)) {
    fields[fieldName] = flowrate;
}

// ---- Build final payload ----
msg.payload = [{
    measurement: measurementName,
    tags: {
        Device: tag1Name,
        Quantity: tag2Name
    },
    fields: fields
}];

return msg;

